// Ported from the Node app's Sequelize model Photo (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class PhotoConfiguration : IEntityTypeConfiguration<Photo>
{
    public void Configure(EntityTypeBuilder<Photo> builder)
    {
        builder.ToTable("photos");
        builder.ConfigureAudit();
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Entity).HasColumnName("entity").HasColumnType("nvarchar(20)").HasMaxLength(20).IsRequired();
        builder.Property(e => e.EntityId).HasColumnName("entity_id");
        builder.Property(e => e.MimeType).HasColumnName("mime_type").HasColumnType("nvarchar(30)").HasMaxLength(30).IsRequired();
        builder.Property(e => e.Size).HasColumnName("size");
        builder.Property(e => e.OriginalName).HasColumnName("original_name").HasColumnType("nvarchar(120)").HasMaxLength(120);
        builder.Property(e => e.Data).HasColumnName("data").HasColumnType("nvarchar(max)").IsRequired();
        builder.Property(e => e.UploadedByName).HasColumnName("uploaded_by_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.Property(e => e.CreatedAt).HasColumnName("created_at").HasColumnType("datetime2");
        builder.Property(e => e.UpdatedAt).HasColumnName("updated_at").HasColumnType("datetime2");
        builder.HasIndex(e => new { e.Entity, e.EntityId }).IsUnique().HasDatabaseName("uq_photo_owner");
    }
}
